import app from 'flarum/forum/app';
import { extend } from 'flarum/common/extend';
import Link from 'flarum/common/components/Link';
import Icon from 'flarum/common/components/Icon';
import classList from 'flarum/common/utils/classList';
import GlobalSearch from 'flarum/forum/components/GlobalSearch';
import IndexPage from 'flarum/forum/components/IndexPage';
import DiscussionPage from 'flarum/forum/components/DiscussionPage';
import Sidebar from './components/Sidebar';
import { closeDrawer, isDrawerOpen, toggleDrawer } from './drawer';
import { currentTag } from './channels';
import formatCount from './formatCount';
const t = (key, params = {}) => app.translator.trans(`ernestdefoe-lobby.forum.${key}`, params);

/**
 * The parts of Lobby that are on every page: the sidebar, and on phones the
 * top bar and the tab bar.
 *
 * 🚨 Mounted next to the router rather than inside a page, the same way core
 * mounts its own header. A page component only exists while its route does,
 * so a sidebar drawn by IndexPage would vanish on every discussion and
 * profile; mounted here it is one element for the whole session, and
 * `m.mount` puts it on the same redraw as everything else.
 */
export default function installShell() {
  extend(app, 'mount', () => {
    const root = document.getElementById('app');
    if (!root) return;
    const mount = (tag, className, component, before = false) => {
      const el = document.createElement(tag);
      el.className = className;
      before ? root.prepend(el) : root.append(el);
      m.mount(el, component);
    };
    mount('div', 'LobbyShell-sidebar', Sidebar, true);
    mount('div', 'LobbyShell-topbar', PhoneTopBar, true);
    mount('div', 'LobbyShell-tabbar', TabBar);

    // The scrim behind the open drawer; a tap on it closes the drawer.
    const scrim = document.createElement('div');
    scrim.className = 'LobbyShell-scrim';
    scrim.addEventListener('click', closeDrawer);
    root.append(scrim);
    document.addEventListener('keydown', e => {
      if (e.key === 'Escape' && isDrawerOpen()) closeDrawer();
    });
  });
}

/** What the phone's top bar calls the page. */
function pageTitle() {
  if (app.current.matches(IndexPage)) {
    const tag = currentTag();
    return tag ? tag.name() : t('sidebar.activity', {});
  }
  if (app.current.matches(DiscussionPage)) {
    const discussion = app.current.get('discussion');
    if (discussion) return discussion.title();
  }
  return app.title || app.forum.attribute('title');
}
const PhoneTopBar = {
  view() {
    const onIndex = app.current.matches(IndexPage);
    const hash = onIndex && currentTag();
    return m("header", {
      className: "LobbyTopBar"
    }, onIndex || !app.history.canGoBack() ? m("button", {
      type: "button",
      className: "LobbyTopBar-button",
      "aria-label": t('phone.open_channels'),
      "aria-expanded": isDrawerOpen() ? 'true' : 'false',
      onclick: toggleDrawer
    }, m(Icon, {
      name: "fas fa-bars"
    })) : m("button", {
      type: "button",
      className: "LobbyTopBar-button",
      "aria-label": t('phone.back'),
      onclick: () => app.history.back()
    }, m(Icon, {
      name: "fas fa-chevron-left"
    })), m("h1", {
      className: "LobbyTopBar-title"
    }, hash ? m("span", {
      className: "LobbyTopBar-hash",
      "aria-hidden": "true"
    }, "#") : null, m("span", {
      className: "LobbyTopBar-text"
    }, pageTitle())), m("div", {
      className: "LobbyTopBar-search"
    }, m(GlobalSearch, {
      state: app.search.state
    })));
  }
};
const TabBar = {
  view() {
    const user = app.session.user;
    const route = m.route.get() || '/';
    const messages = !!user && 'flarum-messages' in flarum.extensions;
    const unreadDialogs = user && user.attribute('unreadDialogCount') || 0;
    const alerts = user && user.newNotificationCount() || 0;
    const home = app.current.matches(IndexPage);
    const tab = (key, icon, label, attrs, active, badge = 0) => m(Link, Object.assign({
      key: key
    }, attrs, {
      className: classList('LobbyTab', {
        active
      }),
      "aria-current": active ? 'page' : undefined,
      onclick: e => {
        closeDrawer();
        attrs.onclick?.(e);
      }
    }), m("span", {
      className: "LobbyTab-icon"
    }, m(Icon, {
      name: icon
    }), badge ? m("span", {
      className: "LobbyTab-badge"
    }, formatCount(badge)) : null), m("span", {
      className: "LobbyTab-label"
    }, label));
    return m("nav", {
      className: "LobbyTabBar",
      "aria-label": t('phone.tabs')
    }, tab('home', 'fas fa-house', t('phone.home'), {
      href: app.route('index')
    }, home), messages ? tab('messages', 'far fa-comment', t('sidebar.messages'), {
      href: app.route('messages')
    }, route.startsWith('/messages'), unreadDialogs) : null, user ? tab('alerts', 'far fa-bell', t('phone.alerts'), {
      href: app.route('notifications')
    }, route.startsWith('/notifications'), alerts) : null, user ? tab('you', 'far fa-user', t('phone.you'), {
      href: app.route.user(user)
    }, route.startsWith('/u/' + user.slug())) : tab('you', 'far fa-user', t('phone.log_in'), {
      href: '#',
      onclick: e => {
        e.preventDefault();
        app.modal.show(() => flarum.reg.asyncModuleImport('flarum/forum/components/LogInModal'));
      }
    }, false));
  }
};